window.ScripturaLexicons.BDAG_PART_0385 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-01\" data-source=\"BDAG\" data-search=\"χάραγμα, ατος, τό substantivo neutro marca; imagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χάραγμα, ατος, τό</td><td>substantivo neutro</td><td>marca; imagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-02\" data-source=\"BDAG\" data-search=\"χαρακόω verbo cercar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χαρακόω</td><td>verbo</td><td>cercar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-03\" data-source=\"BDAG\" data-search=\"χαρακτήρ, ῆρος, ὁ substantivo masculino marca; representação; caráter; aparência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χαρακτήρ, ῆρος, ὁ</td><td>substantivo masculino</td><td>marca; representação; caráter; aparência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-04\" data-source=\"BDAG\" data-search=\"χαράκωσις, εως, ἡ substantivo feminino cercamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χαράκωσις, εως, ἡ</td><td>substantivo feminino</td><td>cercamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-05\" data-source=\"BDAG\" data-search=\"χάραξ, ακος, ὁ substantivo masculino estaca; paliçada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χάραξ, ακος, ὁ</td><td>substantivo masculino</td><td>estaca; paliçada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-06\" data-source=\"BDAG\" data-search=\"χαρήσομαι forma verbal; remissão ver χαίρω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χαρήσομαι</td><td>forma verbal; remissão</td><td>ver χαίρω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-07\" data-source=\"BDAG\" data-search=\"χαρίζομαι verbo conceder; cancelar dívida; perdoar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χαρίζομαι</td><td>verbo</td><td>conceder; cancelar dívida; perdoar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-08\" data-source=\"BDAG\" data-search=\"χάριν preposição por causa de; em favor de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χάριν</td><td>preposição</td><td>por causa de; em favor de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-09\" data-source=\"BDAG\" data-search=\"χάρις, ιτος, ἡ substantivo feminino graciosidade; favor; graça; benefício; gratidão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χάρις, ιτος, ἡ</td><td>substantivo feminino</td><td>graciosidade; favor; graça; benefício; gratidão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-10\" data-source=\"BDAG\" data-search=\"χάρισμα, ατος, τό substantivo neutro dom; favor concedido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χάρισμα, ατος, τό</td><td>substantivo neutro</td><td>dom; favor concedido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-11\" data-source=\"BDAG\" data-search=\"χαριτόω verbo favorecer; abençoar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χαριτόω</td><td>verbo</td><td>favorecer; abençoar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-12\" data-source=\"BDAG\" data-search=\"Χαρράν (também Χαράν), ἡ Χαρρά topônimo feminino indeclinável Harã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Χαρράν (também Χαράν), ἡ</td><td>topônimo feminino indeclinável</td><td>Harã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-13\" data-source=\"BDAG\" data-search=\"χάρτης, ου, ὁ substantivo masculino papiro; folha; rolo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χάρτης, ου, ὁ</td><td>substantivo masculino</td><td>papiro; folha; rolo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-14\" data-source=\"BDAG\" data-search=\"χάσμα, ατος, τό substantivo neutro abismo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χάσμα, ατος, τό</td><td>substantivo neutro</td><td>abismo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-15\" data-source=\"BDAG\" data-search=\"χεῖλος, ους, τό substantivo neutro lábio; margem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χεῖλος, ους, τό</td><td>substantivo neutro</td><td>lábio; margem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-16\" data-source=\"BDAG\" data-search=\"χειμάζω verbo expor a tempestade; afligir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χειμάζω</td><td>verbo</td><td>expor a tempestade; afligir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-17\" data-source=\"BDAG\" data-search=\"χείμαρος remissão ver χίμαρος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χείμαρος</td><td>remissão</td><td>ver χίμαρος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-18\" data-source=\"BDAG\" data-search=\"χείμαρροσ/χειμάρρους, ου, ὁ χειμάρροος χείμαρρος substantivo masculino torrente; ravina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χείμαρροσ/χειμάρρους, ου, ὁ</td><td>substantivo masculino</td><td>torrente; ravina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-19\" data-source=\"BDAG\" data-search=\"χειμερινός, ή, όν adjetivo invernal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χειμερινός, ή, όν</td><td>adjetivo</td><td>invernal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0385-20\" data-source=\"BDAG\" data-search=\"χειμών, ῶνος, ὁ substantivo masculino mau tempo; tempestade; inverno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">χειμών, ῶνος, ὁ</td><td>substantivo masculino</td><td>mau tempo; tempestade; inverno</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0385-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χάραγμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χάραγμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">χαράσσω</span>; Soph.+)</p><p class=\"entry-text\">① marca gravada, entalhada, feita a ferro, cortada, impressa, marca, estampilha (Anth. Pal. 6, 63, 6; 7, 220, 2; Anacreontea 27, 2 Preisendanz <span class=\"greek\">πυρός</span> marcas a ferro em cavalos; BGU 453, 8; PGrenf II, 50a, 3 [ambos II d.C., marcas em animais]. Para selos em documentos: CPR 4, 37; PLond II, 277, 20 p. 218 [23 d.C.]; Sb 5231, 11; 5247, 34; 5275, 11 [todos I d.C.]. Uma impressão em moedas: Plut., Ages. 604 [15, 8], Lys. 442 [16, 4], Mor. 211b e outros lugares; POxy 144, 6) em Rv, da marca do Anticristo, que seus adeptos trazem na mão ou na fronte (sobre o assunto v. 3 Macc 2:29; UvWilamowitz, Her 34, 1899, 634f; HLilliebjörn, Über relig. Signierung in d. Antike; mit e. Exkurs über Rv, diss. Upps. ’33): 13:16; 14:9; 20:4. <span class=\"greek\">τὸ</span> <span class=\"greek\">χάρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θηρίου</span> 15:2 v.l.; 16:2; 19:20. <span class=\"greek\">τὸ</span> <span class=\"greek\">χάρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματος</span> <span class=\"greek\">αὐτοῦ</span> 14:11. <span class=\"greek\">τὸ</span> <span class=\"greek\">χάρ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θηρίου</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀριθμὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματος</span> <span class=\"greek\">αὐτοῦ</span> 13:17.—Dssm., NB 68–75 (BS 240–47), LO 289f (LAE 341); JYsebaert, Gk. Baptismal Terminology, ’62, especialmente 196–204.</p><p class=\"entry-text\">② objeto confeccionado por habilidade artística mediante alteração de um material, coisa formada, imagem nas artes representativas <span class=\"greek\">χάρ</span>. <span class=\"greek\">τέχνης</span> uma imagem formada pela arte Ac 17:29 (CIG 6208 <span class=\"greek\">Φοῖβον</span> <span class=\"greek\">χαράττειν</span>; cf. Horace, Sat. I, 8, 1–3).—DELG s.v. <span class=\"greek\">χαράσσω</span> II, 1. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χαρακόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χαρακόω</span> (<span class=\"greek\">χάραξ</span>) 1.º aor. <span class=\"greek\">ἐχαράκωσα</span>; partic. perf. pass. <span class=\"greek\">κεχαρακωμένος</span> cercar (com estacas) (Aeschin. 3, 140; Plut., Cleom. 813 [20, 1]; POxy 729, 23 [II d.C.]; Jer 39:2) <span class=\"greek\">τὶ</span> algo, uma vinha Hs 5, 2, 2f; 5, 4, 1. Pass. 5, 2, 5 (cf. Is 5:2, onde o verbo provavelmente significa ‘prover de estacas [para videiras individuais]’, sentido que é excluído para H por Hs 5, 5, 3 [v. <span class=\"greek\">συγκρατέω</span> 2]).—DELG s.v. <span class=\"greek\">χαράσσω</span> I.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χαρακτήρ, ῆρος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χαρακτήρ</span>, <span class=\"greek\">ῆρος</span>, <span class=\"greek\">ὁ</span> (de <span class=\"greek\">χαράσσω</span> ‘gravar’ por intermédio de <span class=\"greek\">χάραγμα</span>; Aeschyl., Hdt.+; ins, pap, LXX; TestSol 11:6; TestSim 5:4 [‘cópia’, do Livro de Enoque]; ApcSed 7:4; EpArist; Philo; Jos., Ant. 13, 322; Just.; Tat. 17, 2 [nos dois últimos, das letras do alfabeto]; empréstimo na literatura rabínica).</p><p class=\"entry-text\">① marca ou impressão colocada sobre um objeto</p><p class=\"entry-text\">ⓐ da cunhagem de moedas, impressão, reprodução, representação (Eur., El. 559; Aristot., Pol. 1, 6, Oec. 2; Diod S 17, 66, 2; OGI 339, 45; em linguagem figurada Polyb. 18, 34, 7; Philo, Plant. 18) em linguagem figurada IMg 5:2ab.</p><p class=\"entry-text\">ⓑ de uma marca distintiva, marca de fabricante <span class=\"greek\">τὸ</span> <span class=\"greek\">κεφαλοδέσμιον</span> … <span class=\"greek\">χαρακτῆρα</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">βασιλικόν</span> a peça de adorno da cabeça traz uma marca real (isto é, o logotipo de um fabricante que fornece à casa imperial; v. deStrycker ad loc. e AJohnson, Roman Egypt to the Reign of Diocletian ’36, 332–33; 626–27) GJs 2:2. V. 3 abaixo.</p><p class=\"entry-text\">② algo produzido como representação, reprodução, representação, fig., de Deus <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">ἔπλασεν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">εἰκόνος</span> <span class=\"greek\">χαρακτῆρα</span> (Deus) formou um ser humano como reprodução de sua própria identidade/realidade (v. <span class=\"greek\">εἰκών</span> 2) 1 Cl 33:4 (cf. OGI 383, 60 de uma imagem <span class=\"greek\">χ</span>. <span class=\"greek\">μορφῆς</span> <span class=\"greek\">ἐμῆς</span>; 404, 25; Philo, Det. Pot. Ins. 83 chama a alma <span class=\"greek\">τύπον</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χαρακτῆρα</span> <span class=\"greek\">θείας</span> <span class=\"greek\">δυνάμεως</span>). Cristo é <span class=\"greek\">χαρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑποστάσεως</span> <span class=\"greek\">αὐτοῦ</span> uma representação exata do ser real (de Deus) Hb 1:3 (<span class=\"greek\">ὑπόστασις</span> 1a).</p><p class=\"entry-text\">③ traço ou modo característico, marca distintiva (Hdt. e outros; Diod S 1, 91, 7; Dionys. Hal., Ad Pomp. 3, 16; 2 Macc 4:10) <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀποστολικῷ</span> <span class=\"greek\">χαρακτῆρι</span> à maneira apostólica, de uma saudação epistolar ITr ins; cf. 1b acima.</p><p class=\"entry-text\">④ impressão produzida, aspecto exterior, aparência exterior, forma (ApcSed 7:4 <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἥλιος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἀδάμ</span>, <span class=\"greek\">μίαν</span> <span class=\"greek\">χαρακτῆρα</span> <span class=\"greek\">ἦσαν</span> talvez se deva ler sem a vírgula: ‘Ora, o sol e Adão eram semelhantes em aparência’, em contraste com Eva, que era de beleza mais resplandecente que a lua) <span class=\"greek\">εὐειδέσταται</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">χαρακτῆρι</span> excepcionalmente belas em aparência Hs 9, 9, 5.—JGeffcken, Character: ET 21, 1910, 426f; AKörte, Her 64, 1929, 69–86 (história semântica).—DELG s.v. <span class=\"greek\">χαράσσω</span> II 4. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χαράκωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χαράκωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">χαρακόω</span>; Lycurg. Or. §44 p. 153; Plut., Mar. 409 [7, 4]; Dt 20:20) cercamento (v. <span class=\"greek\">χαρακόω</span>) de uma vinha Hs 5, 2, 3.—DELG s.v. <span class=\"greek\">χαράσσω</span> I.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χάραξ, ακος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χάραξ</span>, <span class=\"greek\">ακος</span>, <span class=\"greek\">ὁ</span> (Thu., Aristoph.+; ins, pap, LXX) primariamente ‘estaca pontiaguda’</p><p class=\"entry-text\">① pau/poste pontiagudo usado para cercar uma área, estaca, pl. das estacas usadas para cercar uma vinha (v. <span class=\"greek\">χαρακόω</span> e v. BGU 830, 5 [I d.C.]) Hs 5, 4, 1; 5, 5, 3 (os <span class=\"greek\">χάρακες</span> são frequentemente as estacas que sustentam videiras e outras plantas: Thu. 3, 70, 4; Aristoph., Ach. 986, Vesp. 1291; Theophr., HP 2, 1, 2; Plut., Mor. 4c; Lucian, Philops. 11; BGU 1122, 17 [I a.C.]).</p><p class=\"entry-text\">② instalação militar que envolve o uso de estacas, paliçada, entrincheiramento (variadamente para fins ofensivos ou defensivos: Philo Mech. 82, 34; Polyb. 1, 80, 11; 3, 45, 5; Plut., Aemil. 264 [17, 5], Marcell. 308 [18, 2], Sulla 462 [17, 5]; 469 [28, 3] e outros lugares; Arrian, Exp. Alex. 2, 19, 5 Roos; EpArist 139; Jos., Vi. 214, 395 e outros lugares, Ant. 15, 112; 150 e outros lugares; SIG 363, 1 [297 a.C.]; Is 37:33; Ezk 4:2; 26:8; GWatson, The Roman Soldier ’69 66–68, com cautela quanto à descrição de Vegetius) obra de cerco Lk 19:43 (Theophil. Com. [IV a.C.], Fgm. 9 K. <span class=\"greek\">ἐν</span> <span class=\"greek\">χάρακι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">παρεμβολῇ</span>; para detalhes do cerco v. Jos., BJ 5, 258–6, 442; sobre problemas relacionados com o relato de Lucas v. JFitzmyer, ABD: Luke ad loc.).—DELG s.v. <span class=\"greek\">χαράσσω</span> I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χαρήσομαι</h1><div class=\"entry-meta\"><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χαρήσομαι</span> v. <span class=\"greek\">χαίρω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χαρίζομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χαρίζομαι</span> (<span class=\"greek\">χάρις</span>; Hom.+) médio dep.: fut. <span class=\"greek\">χαρίσομαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:32</a> (também Lucian, Dial. Mort. 9, 1; Jos., Ant. 2, 28; em lugar do ático <span class=\"greek\">χαριοῦμαι</span>); 1.º aor. <span class=\"greek\">ἐχαρισάμην</span>; perf. <span class=\"greek\">κεχάρισμαι</span>. Pass., com sentido pass.: 1.º fut. <span class=\"greek\">χαρισθήσομαι</span> Phlm 22; 1.º aor. <span class=\"greek\">ἐχαρίσθην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:29.</a></p><p class=\"entry-text\">① dar gratuitamente como favor, conceder graciosamente (termo comum em documentos honoríficos que louvam autoridades e pessoas de espírito cívico por sua beneficência, v. índice de SIG e índices de outros corpora de inscrições) de Deus (assim Ael. Aristid. 39, 3 K.=18 p. 409 D.; Herm. Wr. 12, 12; 16, 5 e p. 462, 30; 490, 9; 35; 492, 11 Sc.; 3 Macc 5:11; EpArist 196; TestSim 4:6; Jos., Ant. 3, 87; 4, 317) <span class=\"greek\">θεὸν</span> … <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐκεῖ</span> <span class=\"greek\">θαυμάσια</span> <span class=\"greek\">χαριζόμενον</span> Deus, que concede graciosamente coisas maravilhosas do mundo vindouro (em oposição aos adornos deste mundo, que em contraste são ‘merda’; v. <span class=\"greek\">δεινός</span> e <span class=\"greek\">σκύβαλον</span>) AcPl Ha 2, 23f. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> algo a alguém (Appian, Bell. Civ. 1, 79 §360 <span class=\"greek\">χαρίζεσθαί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σωτηρίαν</span>; Paus. 6, 18, 4 <span class=\"greek\">χαρίσασθαί</span> <span class=\"greek\">μοι</span> <span class=\"greek\">τήνδε</span> <span class=\"greek\">ὦ</span> <span class=\"greek\">βασιλεῦ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χάριν</span>; TestAbr A 3 p. 79, 30 [Stone p. 6] <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπαγγελίαν</span>) Ro 8:32; Phil 2:9; 2 Cl 1:4; Hs 9, 28, 6; D 10:3. Aqui se inclui também Gal 3:18 se <span class=\"greek\">τὴν</span> <span class=\"greek\">κληρονομίαν</span> deve ser suprido pelo contexto (mas v. final desta seção). <span class=\"greek\">τυφλοῖς</span> <span class=\"greek\">ἐχαρίσατο</span> <span class=\"greek\">βλέπειν</span> aos cegos concedeu a capacidade de ver Lk 7:21 (v.l. <span class=\"greek\">τὸ</span> <span class=\"greek\">βλέπειν</span>; cf. Plut., Mor. 609a; 2 Macc 3:31, 33). <span class=\"greek\">ὁ</span> <span class=\"greek\">χαρισάμενος</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">τοιοῦτον</span> <span class=\"greek\">ἐπίσκοπον</span> <span class=\"greek\">κεκτῆσθαι</span> aquele que (por seu favor) vos concedeu obter tal bispo IEph 1:3. Pass. 1 Cor 2:12. <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἐχαρίσθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">πάσχειν</span> foi-vos (graciosamente) concedido o privilégio de sofrer por Cristo Phil 1:29.—<span class=\"greek\">χ</span>. <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> dar ou conceder alguém a alguém (Semonides 7, 93f D.3: Zeus <span class=\"greek\">χαρίζεταί</span> <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span>=Z. concede alguém [isto é, uma boa esposa] a alguém) <span class=\"greek\">κεχάρισταί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">πάντας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πλέοντας</span> <span class=\"greek\">μετά</span> <span class=\"greek\">σου</span> Deus te deu todos os que navegam contigo, isto é, a teu pedido Deus lhes concedeu segurança contra perigo mortal Ac 27:24. Aquele que é ‘dado’ escapa da morte ou de ulterior prisão ao ser entregue àqueles que desejam sua libertação <span class=\"greek\">ᾐτήσασθε</span> <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">φονέα</span> <span class=\"greek\">χαρισθῆναι</span> <span class=\"greek\">ὑμῖν</span> Ac 3:14. Cf. Phlm 22 (Diod S 13, 59, 3 <span class=\"greek\">ἐχαρίσατο</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">συγγενεῖσ</span>=concedeu-lhe seus parentes [capturados] [e os libertou]; Plut., C. Gracch. 836 [4, 3] <span class=\"greek\">χ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">Ὀκτάβιον</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μητρί</span>; PFlor 61, 61 [I d.C.] citado s.v. <span class=\"greek\">ὄχλος</span> 1a, final; Jos., Vi. 355.—Sobre a ‘concessão’ de Barrabás v. JMerkel, Die Begnadigung am Passahfeste: ZNW 6, 1905, 293–316). Por outro lado, entregar um homem àqueles que lhe desejam mal resulta em dano para ele (cf. Jos., Vi. 53) <span class=\"greek\">οὐδείς</span> <span class=\"greek\">με</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">χαρίσασθαι</span> Ac 25:11; cf. v. 16 (sem dat., que é facilmente suprido; a v.l. acrescenta-lhe <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀπώλειαν</span>). Inácio rejeita toda tentativa de outros de salvar-lhe a vida, pois deseja deixar o mundo e estar com Deus, e o martírio abre caminho para isso: <span class=\"greek\">τὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">θέλοντα</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">χαρίσησθε</span> não deis ao mundo aquele que deseja pertencer a Deus IRo 6:2.—Somente com dat. <span class=\"greek\">χ</span>. <span class=\"greek\">τινι</span> mostrar-se gracioso para com alguém (Diod S 14, 11, 1; Appian, Bell. Civ. 2, 112 §467; SIG 354, 4f <span class=\"greek\">βουλόμενος</span> <span class=\"greek\">χαρίζεσθαι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">δήμῳ</span>; ApcEsdr 25:7 <span class=\"greek\">τοὺς</span> <span class=\"greek\">δικαίους</span> <span class=\"greek\">τί</span> <span class=\"greek\">χαρίζεις</span>; Jos., Ant. 17, 222; Eunap. p. 77 Boiss.) Gal 3:18 (v. acima; também Betz, Gal. ad loc.).</p><p class=\"entry-text\">② cancelar uma soma de dinheiro devida, cancelar (Ps.-Aeschin., Ep. 12, 14; Philo, Spec. Leg. 2, 39 <span class=\"greek\">τὰ</span> <span class=\"greek\">δάνεια</span>) Lk 7:42f. Isto constitui uma transição para</p><p class=\"entry-text\">③ mostrar-se gracioso perdoando uma transgressão, perdoar, absolver (Dionys. Hal. 5, 4, 3; Jos., Ant. 6, 144 <span class=\"greek\">ἁμαρτήματα</span> <span class=\"greek\">χαρίζεσθαι</span>) com dat. de pessoa e acus. de coisa (TestJob 43:1 <span class=\"greek\">αὐτοῖς</span> … <span class=\"greek\">τὴν</span> <span class=\"greek\">ἁμαρτίαν</span> <span class=\"greek\">αὐτῶν</span>) <span class=\"greek\">χαρισάμενος</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">παραπτώματα</span> Col 2:13; cf. 2 Cor 2:10a; 12:13. Somente com dat. de pessoa Eph 4:32ab; Col 3:13ab (Plut., Mor. 488a <span class=\"greek\">χαίρειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">χαρίζεσθαι</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νικᾶν</span>=deleitar-se antes em fazer-lhes favores que em vencê-los). Somente com acus. de coisa 2 Cor 2:10bc. Abs. (cf. EpArist 215) antes perdoar 2 Cor 2:7.—B. 1174. DELG s.v. <span class=\"greek\">χάρις</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χάριν</h1><div class=\"entry-meta\"><span>preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χάριν</span> acus. de <span class=\"greek\">χάρις</span>, usado como prep. (B-D-F §160; Rob. 488) e (B-D-F §216, 1; Rob. 647) com gen. (Hom.+; ins, pap, LXX; TestSol 20:2; TestAbr A; JosAs 16:1 cod. A [p. 63, 3 Bat.]; ApcMos 36; Just., Tat.); quase sempre depois da palavra que rege; somente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:12</a> antes dela (uma tendência no grego posterior: SIG índice p. 619b; PTebt 44, 8 [114 a.C.]; 410, 4 [16 d.C.]; PGiss 98, 1 [II d.C.]. A LXX também a tem predominantemente antes: Johannessohn, Kasus 244, 3; igualmente Ar., Tat.) por causa de, em favor de, em razão de.</p><p class=\"entry-text\">ⓐ indicando o objetivo (cf. Hes., Works 709 <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ψεύδεσθαι</span> <span class=\"greek\">γλώσσης</span> <span class=\"greek\">χάριν</span>=não mintas pelo simples propósito de falar; Just., D. 30, 1 <span class=\"greek\">χάριν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">γνῶναι</span>; Tat. 23, 2 <span class=\"greek\">χάριν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φονεύσαι</span>) <span class=\"greek\">τῶν</span> <span class=\"greek\">παραβάσεων</span> <span class=\"greek\">χάριν</span> em vista das transgressões, isto é, para produzi-las e torná-las manifestas Gal 3:19. <span class=\"greek\">αἰσχροῦ</span> <span class=\"greek\">κέρδους</span> <span class=\"greek\">χ</span>. Tit 1:11. Cf. 1 Ti 5:14; Jd 16; 1 Cl 7:4. <span class=\"greek\">τούτου</span> <span class=\"greek\">χάριν</span> para este fim (Appian, Bell. Civ. 4, 89 §375; Just., D. 1, 2) Tit 1:5. <span class=\"greek\">οὗ</span> <span class=\"greek\">χάριν</span> (Appian, Iber. 54 §230; Just., D. 2, 1; PFlor 99, 9 [I/II d.C.]) Dg 11:3. <span class=\"greek\">ὧν</span> <span class=\"greek\">χάριν</span> 1 Cl 55:6.</p><p class=\"entry-text\">ⓑ indicando a razão (Tat. 7, 1 <span class=\"greek\">χάριν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνδραγαθημάτων</span>) <span class=\"greek\">χάριν</span> <span class=\"greek\">τίνος</span> <span class=\"greek\">ἔσφαξεν</span> <span class=\"greek\">αὐτόν</span>; por que razão (=por quê) o matou? 1J 3:12. <span class=\"greek\">οὗ</span> <span class=\"greek\">χάριν</span> por esta razão, portanto (Philo, Op. M. 44) Lk 7:47 (JDublin, <span class=\"greek\">οὗ</span> <span class=\"greek\">χάριν</span> [Lk 7:47]: ET 37, 1926, 525f). <span class=\"greek\">τίνος</span> <span class=\"greek\">χάριν</span>; por que razão? por quê? (Polyb. 2, 42, 1; 3, 9, 1; UPZ 5, 42; 6, 29; JosAs 16 cod. A [p. 63, 2f Bat.]; EpArist 254; Jos., C. Ap. 2, 263; Just., A II, 12, 5; Tat. 4, 1) 1 Cl 31:2.—O <span class=\"greek\">τούτου</span> <span class=\"greek\">χάριν</span> (X., Mem. 1, 2, 54; Plut., Mor. 146e; SIG 888, 70f; BGU 884, 14; 1 Macc 12:45; TestAbr A 13 p. 92, 10 [Stone p. 32]; Jos., Ant. 4, 197) de Eph 3:1, 14 pode ser classificado sob a ou b.—DELG s.v. <span class=\"greek\">χάρις</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χάρις, ιτος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χάρις</span>, <span class=\"greek\">ιτος</span>, <span class=\"greek\">ἡ</span> (Hom.+) acus. bastante predominantemente <span class=\"greek\">χάριν</span>, mas <span class=\"greek\">χάριτα</span> Ac 24:27; 25:9 v.l.; Jd 4 e pl. <span class=\"greek\">χάριτας</span> Ac 24:27 v.l.; 1 Cl 23:1 (Eur., Hel. 1378; Hdt. 6, 41; X., Hell. 3, 5, 16; ins, pap; Zech 4:7; 6:14; EpArist 272, pl. 230.—B-D-F §47, 3; W-S. §9, 7; Mayser 271f; Thackeray 150; Helbing 40f; Mlt-H. 132.—Parece que <span class=\"greek\">χάρις</span> nem sempre se distingue claramente no sentido de <span class=\"greek\">χαρά</span>; Apollodorus [II a.C.]: 244 Fgm. 90 Jac. diz no segundo livro <span class=\"greek\">περὶ</span> <span class=\"greek\">θεῶν</span>: <span class=\"greek\">κληθῆναι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">αὐτὰς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χαρᾶς</span> <span class=\"greek\">Χάριτας</span>· <span class=\"greek\">καὶ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">πολλάκις</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">ποιηταὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χάριν</span> <span class=\"greek\">χαρὰν</span> <span class=\"greek\">καλοῦσιν</span> ‘as [divindades] Cárites são assim chamadas a partir de <span class=\"greek\">χαρά</span> [alegria], pois os poetas frequentemente equiparam <span class=\"greek\">χάρις</span> a <span class=\"greek\">χαρά</span>’. Cf. o jogo de palavras AcPl Ha 8, 7 <span class=\"greek\">χαρᾶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χάριτος</span> a casa estava cheia de alegria e gratidão.).</p><p class=\"entry-text\">① qualidade cativante ou atrativo que suscita uma reação favorável, graciosidade, atratividade, encanto, simpatia (Hom.+; Jos., Ant. 2, 231) da forma e aparência humanas <span class=\"greek\">παῖς</span> <span class=\"greek\">λίαν</span> <span class=\"greek\">εὐειδής</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χάριτι</span> um jovem excepcionalmente belo e cativante AcPl Ha 3, 13. Da fala (Demosth. 51, 9; Ps.-Demetr. [I d.C.], Eloc. §127; 133; 135 e outros lugares; Eccl 10:12; Sir 21:16; Jos., Ant. 18, 208) <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> (gen. de qualidade) as palavras graciosas Lk 4:22. <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">πάντοτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χάριτι</span> seja sempre cativante a vossa conversação Col 4:6 (cf. Plut., Mor. 514f; v. também HAlmqvist, Plut. u. das NT ’46, 121f; Epict. 3, 22, 90). <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">ἐπληροῦτο</span> MPol 12:1 também pode ser situado aqui caso <span class=\"greek\">χάρις</span> não signifique mais que graciosidade (v. 4 abaixo); provavelmente também GJs 7:3 (v. 3b).</p><p class=\"entry-text\">② disposição benéfica para com alguém, favor, graça, cuidado/auxílio gracioso, benevolência (quase um termo técnico no mundo orientado pela reciprocidade e dominado pela influência helênica [cf. p. ex. OGI 669, 29], bem como pelo senso semítico de obrigação social expresso no termo <span class=\"hebrew\" dir=\"rtl\">חֶסֶד</span> [NGlueck, Das Wort ḥesed in alttestamentlichen Sprachgebrauche etc. 1927]. De ordem e espírito diferentes é a modalidade de reciprocidade conhecida como patronato romano, na qual se mantém claramente a superioridade do doador sobre o cliente)</p><p class=\"entry-text\">ⓐ ativo, aquilo que alguém concede a outro, a ação de quem se dispõe voluntariamente a fazer algo que de outro modo não seria obrigatório <span class=\"greek\">χάρις</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτό</span> Lk 2:40. <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (cf. <span class=\"greek\">τῇ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">Κλαυδίου</span> <span class=\"greek\">χάριτι</span> OGI 669, 29) Ac 11:2 D; 14:26. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> 15:40.—Especialmente da intenção benéfica de Deus (cf. <span class=\"greek\">χ</span>. com referência a Deus: Apollon. Rhod. 3, 1005 <span class=\"greek\">σοὶ</span> <span class=\"greek\">θεόθεν</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">ἔσσεται</span>; Dio Chrys. 80 [30], 40 <span class=\"greek\">χ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span>; Ael. Aristid. 13 p. 320 D.; 53 p. 620; Sextus 436b; igualmente na LXX, Philo, Joseph.; SibOr 4, 46=189; 5, 330; Ezk. Trag. 162 [Eus., PE 9, 29, 12].—<span class=\"greek\">χ</span>. para denotar concessões benéficas do imperador: OGI 669, 44 [I d.C.]; BGU 19 I, 21 [II d.C.] <span class=\"greek\">χάρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">Αὐτοκράτορος</span>; 1085 II, 4) e de Cristo, que concedem dons (imerecidos) às pessoas; Deus: <span class=\"greek\">δικαιούμενοι</span> <span class=\"greek\">δωρεὰν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">χάριτι</span> Ro 3:24. Cf. 5:15a, 20f; 6:1; 11:5 (<span class=\"greek\">ἐκλογή</span> 1), 6abc; Gal 1:15 (<span class=\"greek\">διά</span> A 3e); Eph 1:6f (KKuhn, NTS 7, ’61, 337 [referências à literatura de Qumran]); 2:5, 7, 8; cf. Pol 1:3; 2 Th 1:12; 2:16; 2 Ti 1:9; Tit 2:11 (<span class=\"greek\">ἡ</span> <span class=\"greek\">χάρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σωτήριος</span>; v. Dibelius, Hdb. excursus após Tit 2:14); 3:7; Hb 2:9 (<span class=\"greek\">χωρίς</span> 2a<span class=\"greek\">α</span>); 4:16a (DdeSilva, JBL 115, ’96, 100–103); 1 Cl 50:3; ISm 9:2; IPol 7:3. <span class=\"greek\">ἐν</span> <span class=\"greek\">χάρ</span>[<span class=\"greek\">ιτι</span> <span class=\"greek\">θεοῦ</span>] AcPl Ha 7, 23 (restauração incerta). <span class=\"greek\">κατὰ</span> <span class=\"greek\">χάριν</span> como favor, por benevolência (cf. Pla., Leg. 740c; escólio a Soph., Oed. Col. 1751 p. 468 Papag.) Ro 4:4 (oposto a <span class=\"greek\">κατὰ</span> <span class=\"greek\">ὀφείλημα</span>), 16.—A beneficência ou favor de Cristo: <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">πιστεύομεν</span> <span class=\"greek\">σωθῆναι</span> Ac 15:11. Cf. Ro 5:15b; 2 Cor 8:9; 1 Ti 1:14; IPhld 8:1. Sobre Ac 2:47 neste sentido v. TAnderson, NTS 34, ’88, 604–10.</p><p class=\"entry-text\">ⓑ passivo, aquilo que alguém recebe de outro (Arrian, Anab. Alex. 3, 26, 4) <span class=\"greek\">χάριν</span> <span class=\"greek\">ἔχειν</span> ter favor 3J 4 v.l. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> junto a alguém=conquistar seu respeito Ac 2:47 (cf. 2a final; cf. Pind., O. 7, 89f <span class=\"greek\">χάριν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποτ</span>’ <span class=\"greek\">ἀστῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποτὶ</span> <span class=\"greek\">ξείνων</span> conceder-lhe respeito na presença de seus concidadãos e também de estrangeiros); <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span> (Appian, Bell. Civ. 2, 89 §376) Hm 10, 3, 1, cf. 5, 1, 5. <span class=\"greek\">εὑρεῖν</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινι</span> (Philo, Leg. All. 3, 77, final) Lk 1:30; Hs 5, 2, 10; <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">τινος</span> Ac 7:46; GJs 11:2 (JosAs 15:14). <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">μέλλουσι</span> <span class=\"greek\">μετανοεῖν</span> entre aqueles que estão prestes a arrepender-se Hm 12, 3, 3. <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">προέκοπτεν</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνθρώποις</span> Lk 2:52 (indicação de excepcional <span class=\"greek\">ἀρετή</span>, cf. Pind. acima). Cf. Ac 4:33; 7:10 (<span class=\"greek\">ἐναντίον</span> <span class=\"greek\">Φαραώ</span>); Hb 4:16b.—<span class=\"greek\">ποία</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">ἐστίν</span>; que mérito há nisso para vós? Lk 6:32–34; v. D 1:3; 2 Cl 13:4. Cf. 1 Cor 9:16 v.l. Nessas passagens o sentido se aproxima de recompensa (v. Wetter [5 abaixo] 209ff com referências).—Também por metonímia, aquilo que proporciona a alguém o favor (de Deus) ou suscita uma resposta favorável de Deus 1 Pt 2:19, 20.</p><p class=\"entry-text\">ⓒ Na literatura epistolar cristã desde o tempo de Paulo, <span class=\"greek\">χάρις</span> encontra-se no sentido de favor (divino) em fórmulas fixas no início e no fim das cartas (Zahn sobre Gal 1:3; vDobschütz sobre 1 Th 1:1; ELohmeyer, ZNW 26, 1927, 158ff; APujol, De Salutat. Apost. ‘Gratia vobis et pax’: Verb. Dom. 12, ’32, 38–40; 76–82; WFoerster, TW II ’34, 409ff; Goodsp., Probs. 141f. V. também a literatura s.v. <span class=\"greek\">χαίρω</span> 2b). No início de uma carta <span class=\"greek\">χάρις</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰρήνη</span> (subent. <span class=\"greek\">εἴη</span>; New Docs 8, 127f) Ro 1:7; 1 Cor 1:3; 2 Cor 1:2; Gal 1:3; Eph 1:2; Phil 1:2; Col 1:2; 1 Th 1:1; 2 Th 1:2; Phlm 3; Rv 1:4; sem <span class=\"greek\">ὑμῖν</span> Tit 1:4. <span class=\"greek\">χάρις</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰρήνη</span> <span class=\"greek\">πληθυνθείη</span> 1 Pt 1:2; 2 Pt 1:2; 1 Cl ins. <span class=\"greek\">χάρις</span>, <span class=\"greek\">ἔλεος</span>, <span class=\"greek\">εἰρήνη</span> 1 Ti 1:2; 2 Ti 1:2; 2J 3 (sobre a tríade cf. En 5:7 <span class=\"greek\">φῶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰρήνη</span>).—No fim <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> (<span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> etc.) <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ὑμῶν</span> (ou <span class=\"greek\">μετὰ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ὑμῶν</span> etc.) Ro 16:20, 23 (24) v.l.; 1 Cor 16:23; 2 Cor 13:13; Gal 6:18; Eph 6:24; Phil 4:23; Col 4:18; 1 Th 5:28; 2 Th 3:18; 1 Ti 6:21; 2 Ti 4:22; Tit 3:15; Phlm 25; Hb 13:25; Rv 22:21; 1 Cl 65:2. <span class=\"greek\">ἔσται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">φοβουμένων</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Κύριον</span> GJs 25:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ὑμῶν</span> B 21:9. <span class=\"greek\">χάρις</span> <span class=\"greek\">ὑμῖν</span>, <span class=\"greek\">ἔλεος</span>, <span class=\"greek\">εἰρήνη</span>, <span class=\"greek\">ὑπομονὴ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">παντός</span> ISm 12:2. <span class=\"greek\">ἔρρωσθε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">θεοῦ</span> 13:2.</p><p class=\"entry-text\">③ aplicação prática da benevolência, (sinal de) favor, ato/dom gracioso, benefício</p><p class=\"entry-text\">ⓐ da parte de seres humanos (X., Symp. 8, 36, Ages. 4, 3; Appian, Bell. Civ. 1, 49 §213; Dionys. Hal. 2, 15, 4) <span class=\"greek\">χάριν</span> (-<span class=\"greek\">ιτα</span>) <span class=\"greek\">καταθέσθαι</span> <span class=\"greek\">τινί</span> (<span class=\"greek\">κατατίθημι</span> 2) Ac 24:27; 25:9. <span class=\"greek\">αἰτεῖσθαι</span> <span class=\"greek\">χάριν</span> 25:3 (nessas passagens de Ac <span class=\"greek\">χ</span>. sugere favor [político], algo que se faz por outro dentro de um sistema de reciprocidade. Cf. Appian, Bell. Civ. 1, 108 §506 <span class=\"greek\">ἐς</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">Σύλλα</span>=como favor a Sula; ApcSed 8:1 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐποίησάς</span> <span class=\"greek\">μοι</span> <span class=\"greek\">χάριν</span>=não me fizeste favor algum). <span class=\"greek\">ἵνα</span> <span class=\"greek\">δευτέραν</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">σχῆτε</span> para que tivésseis uma segunda prova de minha benevolência 2 Cor 1:15 (a menos que <span class=\"greek\">χάρις</span> aqui signifique deleite [assim na poesia, Pind. e outros, mas também Pla., Isocr.; L-S-J-M s.v. <span class=\"greek\">χάρις</span> IV; cf. também a citação de Apollodorus no início do presente verbete, e o fato de <span class=\"greek\">χαρά</span> ser v.l. em 2 Cor 1:15]; nesse caso <span class=\"greek\">δευτέρα</span> significa duplo; mas v. comentários). Da coleta para Jerusalém (cf. Appian, Bell. Civ. 3, 42 §173 <span class=\"greek\">χάριτας</span> <span class=\"greek\">λαμβάνειν</span>=receber dons) 1 Cor 16:3; 2 Cor 8:4, 6f, 19 (DdeSilva, JBL 115, ’96, 101). Cf. B 21:7.—Eph 4:29 pode sugerir uma manifestação de favor humano (cf. Plut., Mor. 514e <span class=\"greek\">χάριν</span> <span class=\"greek\">παρασκευάζοντες</span> <span class=\"greek\">ἀλλήλοις</span>), mas não se deve excluir uma referência ao meio pelo qual a graça divina é mediada (v. b abaixo).</p><p class=\"entry-text\">ⓑ da parte de Deus e de Cristo; o contexto mostrará se a ênfase recai sobre a posse do favor divino como fonte de bênçãos para o crente, ou sobre uma reserva de favor que é dispensada, ou uma condição favorecida (isto é, estar no favor de Deus) que é produzida, ou um ato gracioso realizado por Deus em Cristo, ou uma obra graciosa que cresce cada vez mais (assim em contraste com a antiga aliança Mel., P. 3, 16 e outros lugares). Deus é chamado <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">χάριτος</span> 1 Pt 5:10, isto é, Deus, que se distingue por todo benefício ou favor concebível; cf. B 21:9.—<span class=\"greek\">χάριν</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">τινί</span> mostrar favor a alguém (Anacr. 110 Diehl; Appian, Ital. 5 §10): <span class=\"greek\">τὸν</span> <span class=\"greek\">δόντα</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χάριν</span> GJs 14:2. <span class=\"greek\">ταπεινοῖς</span> <span class=\"greek\">δίδωσι</span> <span class=\"greek\">χάριν</span> (Pr 3:34) Js 4:6b; 1 Pt 5:5; 1 Cl 30:2; sem dat. Js 4:6a (Menand., Epitr. 231 S. [55 Kö.]). Talvez <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔβαλλε</span> <span class=\"greek\">κύριος</span> … <span class=\"greek\">χάριν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτήν</span> GJs 7:3 (mas v. 1 acima). O Logos é <span class=\"greek\">πλήρης</span> <span class=\"greek\">χάριτος</span> J 1:14. Os que lhe pertencem recebem da plenitude de sua graça, <span class=\"greek\">χάριν</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">χάριτος</span> v. 16 (<span class=\"greek\">ἀντί</span> 2). Cf. v. 17. <span class=\"greek\">τὴν</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾗ</span> <span class=\"greek\">ἑστήκαμεν</span> este favor (de Deus) de que agora desfrutamos Ro 5:2 (Goodsp.).—5:17; 1 Cor 1:4; 2 Cor 4:15 (beneficência divina na conversão); cf. Ac 11:23; 6:1; Gal 1:6 (pelo ato gracioso de Cristo); 2:21; 5:4; Col 1:6; 2 Ti 2:1; Hb 12:15; 13:9; 1 Pt 1:10, 13; 3:7 (<span class=\"greek\">συνκληρονόμοι</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">ζωῆς</span> coerdeiros do dom que significa vida; v. <span class=\"greek\">ζωή</span> 2b<span class=\"greek\">α</span>); 5:12; 2 Pt 3:18; Jd 4; IPhld 11:1; ISm 6:2. Os cristãos estão <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">χάριν</span> sob a vontade graciosa de Deus, expressa em sua libertação da restrição legal Ro 6:14f, ou passam a estar <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ζυγὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">αὐτοῦ</span> 1 Cl 16:17 (<span class=\"greek\">ζυγός</span> 1). A proclamação da salvação é a mensagem da beneficência divina <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Ac 20:24 ou <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>) 14:3; 20:32. Até a mensagem do evangelho pode ser chamada <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> 13:43; cf. 18:27; MPol 2:3. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> o Espírito do qual ou por meio do qual se manifesta o favor (de Deus) Hb 10:29 (AArgyle, Grace and the Covenant: ET 60, ’48/49, 26f).—Pl. benefícios, favores (Diod S 3, 2, 4; 3, 73, 6; Sb 8139, 4 [inscrição do I a.C.] de Ísis; Jos., C. Ap. 2, 190) 1 Cl 23:1.—Nelson Glueck, Das Wort ḥesed etc. 1927, mas v. FAndersen, ‘Yahweh, the Kind and Sensitive God’: God Who is Rich in Mercy, ed. PO’Brien/DPeterson ’86.</p><p class=\"entry-text\">④ efeito excepcional produzido pela generosidade, favor. Dos efeitos produzidos pela beneficência divina que excedem aqueles associados à condição de determinado cristão (ins <span class=\"greek\">μεγάλαι</span> <span class=\"greek\">χάριτες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεου</span>: FCumont, Syria 7, 1926, 347ff), nas congregações da Macedônia 2 Cor 8:1 e de Corinto 9:14; cf. v. 8; em Roma AcPl Ha 7, 8. O confessor cristão está em plena posse da graça divina ISm 11:1. Paulo sabe que mediante a <span class=\"greek\">χάρις</span> de Deus foi chamado a ser apóstolo e que da mesma fonte foi dotado dos poderes e capacidades necessários a esse ofício: Ro 1:5; 12:3; 15:15; 1 Cor 3:10; 15:10ab (quanto ao assunto cf. Polyb. 12, 12b, 3 <span class=\"greek\">αὐτὸν</span> [Alexandre, o Grande] <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δαιμονίου</span> <span class=\"greek\">τετευχέναι</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἔτυχεν</span>=tudo quanto recebeu, recebeu do que é divino. [Por essa razão não merece quaisquer honras divinas.]); 2 Cor 12:9; Gal 2:9; Eph 3:2, 7f; Phil 1:7.—A <span class=\"greek\">χάρις</span> de Deus manifesta-se em diversos <span class=\"greek\">χαρίσματα</span>: Ro 12:6; Eph 4:7; 1 Pt 4:10. Isto traz à consideração várias passagens em que <span class=\"greek\">χάρις</span> evidentemente deve ser entendida em sentido muito concreto. Dificilmente se distingue de <span class=\"greek\">δύναμις</span> (<span class=\"greek\">θεοῦ</span>) ou de <span class=\"greek\">γνῶσις</span> ou <span class=\"greek\">δόξα</span> (v. esse verbete 1b. Sobre este assunto v. Wetter [5 abaixo] p. 94ff; especialmente 130ff; pap no GLumbroso Festschr. 1925, 212ff: <span class=\"greek\">χάρις</span>, <span class=\"greek\">δύναμις</span>, <span class=\"greek\">πνεῦμα</span> com essencialmente o mesmo sentido; PGM 4, 2438; 3165; Herm. Wr. 1, 32; Just., D. 87, 5 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δυνάμεως</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span>). <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σοφίᾳ</span> <span class=\"greek\">σαρκικῇ</span> <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">ἐν</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">θεοῦ</span> 2 Cor 1:12. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ἐμοί</span> 1 Cor 15:10c. <span class=\"greek\">αὐξάνετε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γνώσει</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> 2 Pt 3:18; cf. 1 Cl 55:3; B 1:2 (<span class=\"greek\">τῆς</span> <span class=\"greek\">δωρεᾶς</span> <span class=\"greek\">πνευματικῆς</span> <span class=\"greek\">χάρις</span>). Diz-se que Estêvão é <span class=\"greek\">πλήρης</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δυνάμεως</span> Ac 6:8. O poder divino enche o confessor ou mártir cristão de um resplendor radiante MPol 12:1 (mas v. 1 acima). Como qualidade típica do século vindouro, em contraste com o <span class=\"greek\">κόσμος</span> D 10:6.</p><p class=\"entry-text\">⑤ resposta à generosidade ou beneficência, agradecimento, gratidão (componente fundamental do sistema greco-romano de reciprocidade; exemplos de épocas posteriores: Diod S 11, 71, 4 [<span class=\"greek\">χάριτες</span>=provas de gratidão]; Appian, Syr. 3, 12; 13. Cf. Wetter [abaixo] p. 206f) <span class=\"greek\">χάριν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τινί</span> ser grato a alguém (Eur., Hec. 767; X., An. 2, 5, 14; Pla., Phlb. 54d; Ath. 2, 1; PLips 104, 14 [I a.C.] <span class=\"greek\">χάριν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ἔχω</span>) seguido de <span class=\"greek\">ὅτι</span> (Epict. 3, 5, 10; Jos., C. Ap. 1, 270; 2, 49) Lk 17:9 (ERiggenbach, NKZ 34, 1923, 439–43); sobretudo da gratidão a Deus ou a Cristo; <span class=\"greek\">χάρις</span> em nossa literatura como um todo, no sentido de gratidão, refere-se à resposta apropriada à Divindade pelos benefícios conferidos (Hom., Pind., Thu. e outros; ins, pap, LXX; Jos., Ant. 7, 208) <span class=\"greek\">χάριν</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> (POxy 113, 13 [II d.C.] <span class=\"greek\">χάριν</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">πᾶσιν</span>.—Epict. 4, 7, 9) 2 Ti 1:3; seguido de <span class=\"greek\">ὅτι</span> porque 1 Ti 1:12 (Herm. Wr. 6, 4 <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> … , <span class=\"greek\">ὅτι</span>; Jos., Ant. 4, 316); <span class=\"greek\">χάριν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> ser grato por algo Phlm 7 v.l. (a seres humanos). <span class=\"greek\">ἔχωμεν</span> <span class=\"greek\">χάριν</span> sejamos gratos (a Deus) Hb 12:28 (a razão disso é dada pelo partic. precedente <span class=\"greek\">παραλαμβάνοντες</span>). Elipticamente (B-D-F §128, 6; cf. Rob. 1201f) <span class=\"greek\">χάρις</span> (<span class=\"greek\">ἔστω</span>) <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> (X., Oec. 8, 16 <span class=\"greek\">πολλὴ</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>; Epict. 4, 4, 7 <span class=\"greek\">χάρις</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῳ</span>; BGU 843, 6 [I/II d.C.] <span class=\"greek\">χάρις</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span> e outros lugares em pap desde III a.C..—Philo, Rer. Div. Her. 309) Ro 7:25; MPol 3:1. Seguido de <span class=\"greek\">ὅτι</span> (X., An. 3, 3, 14 <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">ὅτι</span>; PFay 124, 16 <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">χάρις</span> <span class=\"greek\">ὅτι</span>; Epict. 4, 5, 9) Ro 6:17. Seguido de <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> por algo (UPZ 108, 30 [99 a.C.]) 2 Cor 9:15. A razão do agradecimento é dada no partic. concordante com <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> 2:14; 8:16; 1 Cor 15:57 (cf. Jos., Ant. 6, 145; Philo, Somn. 2, 213). Gratidão (Appian, Bell. Civ. 3, 15 §51 <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span>=para com alguém) <span class=\"greek\">χάριτι</span> com gratidão 10:30. Assim provavelmente também <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χάριτι</span> em espírito de gratidão Col 3:16 (Dibelius, Hdb. ad loc.). <span class=\"greek\">πλησθῆναι</span> <span class=\"greek\">χαρᾶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χάριτος</span> AcPl Ha 8, 7. V. <span class=\"greek\">εὐχαριστέω</span>, final. Também PSchubert, Form and Function of the Pauline Thanksgivings ’39.—OLoew, <span class=\"greek\">Χάρις</span>, diss., Marburg 1908; GWetter, Charis 1913; AvHarnack, Sanftmut, Huld u. Demut in der alten Kirche: JKaftan Festschr. 1920, 113ff; NBonwetsch, Zur Geschichte des Begriffs Gnade in der alten Kirche: Harnack Festgabe 1921, 93–101; EBurton, Gal ICC 1921, 423f; WWhitley, The Doctrine of Grace ’32; JMoffatt, Grace in the NT ’31; RWinkler, D. Gnade im NT: ZST 10, ’33, 642–80; RHomann, D. Gnade in d. Syn. Ev.: ibid. 328–48; JWobbe, D. Charisgedanke b. Pls ’32; RBultmann, Theologie des NT ’48, 283–310 (Paulo); HBoers, <span class=\"greek\">Ἀγάπη</span> and <span class=\"greek\">Χάρις</span> in Paul’s Thought: CBQ 59, ’97, 693–713; sobre 2 Cor 8: FDanker, Augsburg Comm. 2 Cor, 116–34; PRousselot, La Grâce d’après St. Jean et d’après St. Paul: SR 18, 1928, 87–108, Christent. u. Wissensch. 8, ’32, 402–30; JMontgomery, Hebrew Hesed and Gk. Charis: HTR 32, ’39, 97–102; Dodd 61f; TTorrance, The Doctrine of Grace in the Apost. Fathers, ’48; JRenié, Studia Anselmiana 27f, ’51, 340–50; CRSmith, The Bible Doctrine of Grace, ’56; EFlack, The Concept of Grace in Bibl. Thought: Bibl. Studies in Memory of HAlleman, ed. Myers, ’60, 137–54; DDoughty, NTS 19, ’73, 163–80.—B. 1166. DELG. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χάρισμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χάρισμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">χαρίζομαι</span>) aquilo que é dado gratuitamente e graciosamente, favor concedido, dom (Sir 7:33 v.l.; 38:30 v.l.; Theod. Ps 30:22; TestSol; OdeSol 11:10; Philo, Leg. All. 3, 78 [duas vezes]: <span class=\"greek\">γενέσεως</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">χάρισμα</span> e <span class=\"greek\">δωρεὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εὐεργεσία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χάρισμα</span> <span class=\"greek\">θεοῦ</span>; SibOr 2, 54 <span class=\"greek\">θεοῦ</span> <span class=\"greek\">χ</span>.; Just., D. 82, 1; 88, 1.—Alciphron 3, 17, 4 [é possível que isto provenha da comédia ática: Kock III p. 677]; BGU 1044, 4 [IV d.C.] de benefícios conferidos. Outros exemplos não judaicos/cristãos da palavra provêm de épocas posteriores: BGU 551, 3; PLond I, 77, 24 p. 233; Sb 4789, 7; Achmes 4, 13; Nicetas Eugen. 6, 537f) em nossa literatura somente de dons da beneficência divina.</p><p class=\"entry-text\">ⓐ geralmente, os bens terrenos concedidos por Deus D 1:5. Os privilégios concedidos ao povo de Israel Ro 11:29. O dom gracioso do livramento de perigo mortal 2 Cor 1:11. A possessão espiritual do crente Ro 1:11 (<span class=\"greek\">χάρισμα</span> <span class=\"greek\">πνευματικόν</span>); 1 Cor 1:7; ISm ins; IPol 2:2. O dom gracioso da redenção Ro 5:15f; IEph 17:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">χάρισμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">αἰώνιος</span> Ro 6:23.</p><p class=\"entry-text\">ⓑ de dons especiais de natureza imaterial, concedidos pela generosidade de Deus a cristãos individuais 1 Pt 4:10; 1 Cl 38:1. Do dom para a realização de tarefas especiais, mediado pela imposição de mãos 1 Ti 4:14; 2 Ti 1:6. Da capacidade de ser continente em assuntos sexuais 1 Cor 7:7. De dons espirituais em sentido especial (Just., D. 82, 1 e Iren. 5, 6, 1 [Harv. II 334, 2] <span class=\"greek\">προφητικὰ</span> <span class=\"greek\">χ</span>.; Orig., C. Cels. 3, 46, 12; Hippol., Ref. 8, 19, 2) Ro 12:6; 1 Cor 12:4, 9, 28, 30, 31.—V. além da literatura s.v. <span class=\"greek\">γλῶσσα</span> 3 também GWetter, Charis 1913, 168–87; EBuonaiuti, I Carismi: Ricerche religiose 4, 1928 259–61; FGrau, Der ntliche Begriff <span class=\"greek\">Χάρισμα</span>, diss. Tübingen ’47; HHCharles, The Charismatic Life in the Apost. Church, diss. Edinburgh, ’58; APiepkorn, CTM 42, ’71, 369–89 (NT e Padres Apostólicos); ENardoni, The Concept of Charism in Paul: CBQ 55, ’93, 68–80; TRE VII 688–93.—DELG s.v. <span class=\"greek\">χάρις</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χαριτόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χαριτόω</span> (<span class=\"greek\">χάρις</span>) 1.º aor. <span class=\"greek\">ἐχαρίτωσα</span>; partic. perf. pass. <span class=\"greek\">κεχαριτωμένος</span> (Sir 18:17; Ps 17:26 Sym.; EpArist 225; TestJos 1:6; BGU 1026, XXIII, 24 [IV d.C.]; Cat. Cod. Astr. XII 162, 14; Rhet. Gr. I 429, 31; Achmes 2, 18) fazer que alguém seja destinatário de um benefício, conceder favor a, favorecer grandemente, abençoar, em nossa literatura somente com referência à <span class=\"greek\">χάρις</span> divina (mas Did., Gen. 162, 8 de Noé <span class=\"greek\">διὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀρετῆς</span> <span class=\"greek\">ἔργων</span> <span class=\"greek\">χαριτώσας</span> <span class=\"greek\">ἑαυτόν</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ἐχαρίτωσεν</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">πράξει</span> <span class=\"greek\">αὐτῶν</span> Hs 9, 24, 3. <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">αὐτοῦ</span> (=<span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>), <span class=\"greek\">ἧς</span> <span class=\"greek\">ἐχαρίτωσεν</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἠγαπημένῳ</span> o grande favor de Deus, com o qual nos favoreceu por meio de seu amado (Filho) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:6.</a> Pass. (Libanius, Progymn. 12, 30, 12 vol. VIII p. 544, 10 F. <span class=\"greek\">χαριτούμενος</span>=favorecido; cf. Geminus [I a.C.], Elem. Astronomiae [Manitius 1898] 8, 9 <span class=\"greek\">κεχαρισμένον</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>) na saudação do anjo a Maria <span class=\"greek\">κεχαριτωμένη</span> aquela que foi favorecida (por Deus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:28</a> (SLyonnet, Biblica 20, ’39, 131–41; MCambe, RB 70, ’63, 193–207; JNolland, Luke’s Use of <span class=\"greek\">χάρις</span>: NTS 32, ’86, 614–20); GJs 11:1.—DELG s.v. <span class=\"greek\">χάρις</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Χαρράν (também Χαράν), ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Χαρράν</span> (<span class=\"greek\">Χαράν</span> TestIss 1:5 Charles; Just., D. 58, 11; <span class=\"hebrew\" dir=\"rtl\">חָרָן</span>. Gen 11:31f; 12:4f; 27:43; Philo; TestLevi 2:1), <span class=\"greek\">ἡ</span> indecl. (Jos., Ant. 1, 152; 285* <span class=\"greek\">εἰς</span> [<span class=\"greek\">τὴν</span>] <span class=\"greek\">Χαρράν</span> é seguramente acus. de <span class=\"greek\">Χαρρά</span>) Harã, lugar na Mesopotâmia (=<span class=\"greek\">Κάρραι</span>, Carrhae, célebre pela derrota de Crasso que ali ocorreu em 53 a.C.), onde Abraão viveu por algum tempo (Gen 11:31; Demetr.: 722 Fgm. 1, 18 Jac.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:2,</a> 4.—BHHW II 647.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χάρτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χάρτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (desde o poeta cômico Platão [IV a.C.] em Pollux 7, 210; Theopompus [IV a.C.]: 115 Fgm. 263 Jac. p. 592, 28 [em <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 43, 2] <span class=\"greek\">χάρται</span> <span class=\"greek\">βυβλίων</span>; ins, pap; Jer 43:23; TestSol; TestAbr A 12 p. 91, 3 [Stone p. 30]; ParJer; Jos., C. Ap. 1, 307; empréstimo na literatura rabínica) papiro, geralmente entendido no sentido de uma folha de papel (assim Cebes 4, 3; Plut., Mor. 900b; Leo 1, 3 e outros lugares; Anth. Pal. 9, 401, 3; 174, 4; 6; Geopon. 13, 5, 4. Frequentemente em pap; v. especialmente PFlor 367, 7 <span class=\"greek\">χάρτας</span> <span class=\"greek\">ἐπιστολικούς</span> papel de carta, material de escrita.—Sobre a palavra v. GGlotz, Bull. Soc. Arch. Alex. 25, 1930, 83–96; Preis., Wörterb.). Mas em vários pap (PCairZen 654, 46; 687, 7f; PColZen I, 4), evidentemente significa um rolo de papiro (não escrito) (APF 10, ’32, 241; 11, ’35, 286f; NLewis, L’industrie du Papyrus ’34; Gnomon 12, ’36, 48) 2J 12 (com <span class=\"greek\">μέλαν</span>; ParJer <span class=\"greek\">ἤνεγκε</span> <span class=\"greek\">χάρτην</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μέλανα</span>).—TBirt, Das antike Buchwesen 1882; KDziatzko, Untersuchungen über ausgewählte Kapitel des antiken Buchwesens 1900; VGardthausen, Das Buch im Altertum 1911; WSchubart, Das Buch bei den Griechen u. Römern2 1921, 34; Nestle/Dobschütz, Einführung in das griechische NT4 1923, 32f; 78; JČerný, Paper and Books in Ancient Egypt ’52.—B. 1289. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χάσμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χάσμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">χάσκω</span> ‘bocejar, escancarar-se’; Hes. e outros; Eur.; Hdt. 4, 85; Philo; Jos., Bell. 5, 566, Ant. 6, 27; 7, 242; 2 Km 18:17 <span class=\"greek\">χ</span>. <span class=\"greek\">μέγα</span>; En 18:11 <span class=\"greek\">χ</span>. <span class=\"greek\">μέγα</span>) abismo (lit. ‘uma abertura escancarada’), do espaço intransponível entre Abraão e o lugar de tormento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:26</a> (Diog. L. 8, 31: segundo Pitágoras, as <span class=\"greek\">ψυχαὶ</span> <span class=\"greek\">ἀκάθαρτοι</span> não podem aproximar-se do <span class=\"greek\">ὕψιστος</span> <span class=\"greek\">τόπος</span> ao qual Hermes conduziu as <span class=\"greek\">ψυχαὶ</span> <span class=\"greek\">καθαραί</span>; cf. 1 Esdr 7:10–15; sobre o caráter definitivo cf. 2 Cl 8:3; Pind. O. 2, 53–78).—DELG s.v. <span class=\"greek\">χαίνω</span> II.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χεῖλος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χεῖλος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> gen. pl. não contraído <span class=\"greek\">χειλέων</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:15</a> [de Hos 14:3]; B-D-F §48; Mlt-H. 139) ‘lábio’</p><p class=\"entry-text\">① os lábios, pl. (Hom.+; pap, LXX, PsSol; OdeSol 11:6; TestSol 18:20; TestIss 7:4; JosAs, Philo; Just., A I, 32, 8, D. 101, 3) enquanto usados na fala Mt 15:8; Mk 7:6; 1 Cl 15:2; 2 Cl 3:5; cf. 4 (todos Is 29:13); Ro 3:13 (Ps 139:4); Hb 13:15 (Hos 14:3); 1 Pt 3:10 (Ps 33:14); 1 Cl 15:5 (Ps 30:19); 18:15 (Ps 50:17); 22:3 (Ps 33:14). <span class=\"greek\">ἐν</span> <span class=\"greek\">χείλεσιν</span> <span class=\"greek\">ἑτέρων</span> <span class=\"greek\">λαλήσω</span> 1 Cor 14:21 (Is 28:11, mas significativamente diferente). Em outro sentido, de um gesto de escárnio <span class=\"greek\">λαλεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">χείλεσιν</span> 1 Cl 16:16 (Ps 21:8). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">χείλεσιν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τινά</span> ter alguém (isto é, seu nome) nos lábios e nada mais (Dio Chrys. 15 [32], 50 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">χείλεσι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχὰς</span> <span class=\"greek\">ἔχειν</span>) Hm 12, 4, 4; também <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">χείλη</span> Hs 9, 21, 1.</p><p class=\"entry-text\">② praia, margem, sing. (de um rio: Hdt. 2, 94; Polyb. 3, 14, 6 e outros lugares; Diod S 3, 10, 2; 20, 75, 3; de rios e pântanos Aristot., HA 6, 16; de um lago Jos., Bell. 3, 511) do mar (TestAbr A 1 p. 78, 1 [Stone p. 4]; ApcEsdr 3:10 p. 27, 20 Tdf.; ApcSed 8:9 p. 133, 14 Ja.; Achilles Tat. 2, 18, 2) Hb 11:12 (Gen 22:17). <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰορδάνου</span> PEg2 66.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειμάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χειμάζω</span> (<span class=\"greek\">χεῖμα</span> ‘tempo de inverno’; Aeschyl., Thu. e outros; ins, pap; Pr 26:10; En 101:5; Test12Patr)</p><p class=\"entry-text\">① expor a mau tempo, açoitar numa tempestade, em nossa literatura de uma tempestade real que impede a navegação, e na pass. (cf. Aeschyl., Prom. 840; Pla., Phlb. 29a; Diod S 3, 55, 8; 5, 58, 2 <span class=\"greek\">κεχειμασμένος</span> <span class=\"greek\">ἰσχυρῶς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πλοῦν</span>; Ael. Aristid. 44, 13 K.=17 p. 405 D.: <span class=\"greek\">χειμαζόμενος</span>; En 101:5; TestNapht 6:5; Jos., Ant. 12, 130 e outros lugares) <span class=\"greek\">σφοδρῶς</span> <span class=\"greek\">χειμαζομένων</span> Ac 27:18. Em linguagem figurada (Polystrat. p. 31; Epict., Fgm. Stob. 47; Jos., Bell. 3, 195; TestJud 21:6) IPol 2:3.</p><p class=\"entry-text\">② causar aflição física ou psicológica, afligir, de uma gravidez <span class=\"greek\">ἴσως</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> <span class=\"greek\">χειμάζει</span> <span class=\"greek\">αὐτήν</span> talvez aquilo que está nela a esteja afligindo GJs 17:2 (v. deStrycker p. 308).—DELG s.v. <span class=\"greek\">χεῖμα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείμαρος</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χείμαρος</span> v. <span class=\"greek\">χίμαρος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείμαρροσ/χειμάρρους, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χείμαρροσ</span>/<span class=\"greek\">χειμάρρους</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">χεῖμα</span> ‘tempo de inverno’, <span class=\"greek\">ῥέω</span>; desde Hom. [<span class=\"greek\">χειμάρροος</span> e <span class=\"greek\">χείμαρρος</span> Il. 4, 452; 5, 88] predominantemente na forma <span class=\"greek\">χειμάρρους</span>, que também prevalece em toda a LXX [<span class=\"greek\">χείμαρρος</span> com certeza somente Ps 123:4, mas também EpArist 117; SibOr 13, 55; v. Thackeray 144; Helbing 34], assim como em Philo [Rer. Div. Her. 32] e em Joseph. [Ant. 6, 360; com <span class=\"greek\">χείμαρρος</span> 314]) curso de água que flui abundantemente no inverno (a Suda o define: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">χειμῶνι</span> <span class=\"greek\">ῥέων</span> <span class=\"greek\">ποταμός</span>; Polyb. 4, 70, 7 e Artem. 2, 27 acrescentam <span class=\"greek\">ποταμός</span> a <span class=\"greek\">χ</span>.), torrente de inverno, ravina, uádi <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:1</a> (v. <span class=\"greek\">Κεδρών</span> e Jos., Ant. 8, 17 <span class=\"greek\">τὸν</span> <span class=\"greek\">χειμάρρουν</span> <span class=\"greek\">Κεδρῶνα</span>). <span class=\"greek\">ἐπέβλεψα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χείμαρρον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ποταμοῦ</span> olhei para o fluxo do curso de água GJs 18:3.—B. 42. DELG s.v. <span class=\"greek\">χεῖμα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειμερινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χειμερινός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Hdt. e outros; ins, pap, LXX, En 17:7; Philo) relativo ao inverno, invernal <span class=\"greek\">καιροὶ</span> <span class=\"greek\">χειμερινοί</span> estações de inverno 1 Cl 20:9 (Diod S 14, 100, 5; 15, 65, 2 <span class=\"greek\">χειμερινὴ</span> <span class=\"greek\">ὥρα</span>=estação de inverno).—DELG s.v. <span class=\"greek\">χεῖμα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0385-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειμών, ῶνος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">χειμών</span>, <span class=\"greek\">ῶνος</span>, <span class=\"greek\">ὁ</span>(Hom.+, em vários sentidos relativos a tempo inclemente/mau tempo; os contextos geralmente qualificam o caráter específico de tal tempo, para o qual uma língua receptora pode ter termos distintos)</p><p class=\"entry-text\">① tempo tempestuoso, mau tempo, tempestade (Hom. e outros; Sb 998 [16/17 d.C.]; LXX; En 101:4; Test12Patr; Joseph.) <span class=\"greek\">σήμερον</span> <span class=\"greek\">χειμών</span> hoje haverá tempo tempestuoso Mt 16:3. No mar, tempestade, mau tempo: <span class=\"greek\">χειμῶνος</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὀλίγου</span> <span class=\"greek\">ἐπικειμένου</span> com tempo bastante adverso a oprimi-los (indicativo de uma área de baixa pressão) Ac 27:20. Para esta passagem muitos traduzem tempestade (cf. Demosth. 18, 194; Diod S 11, 13, 1 <span class=\"greek\">χ</span>. <span class=\"greek\">μέγας</span>=uma tempestade severa; TestNapht 6:9; Jos., Ant. 6, 91; 14, 377; fig.: Philo, Congr. Erud. Gr. 93 [oposto a <span class=\"greek\">γαλήνη</span>] e Tat. 6, 3 uma ‘borrasca’ de estupidez); baseando-se, segundo Warnecke, Romfahrt 41 (n. 10; v. também p. 46), em concepções errôneas relativas às condições meteorológicas e aos dados geográficos e sem levar devidamente em conta a improvável proeza de navegar através de uma tempestade violenta por duas semanas (Ac 27:27; v. Romfahrt 41–54).</p><p class=\"entry-text\">② a estação de mau tempo, inverno (Hom., Hdt., Thu., Aristoph.+; ins, pap; SSol 2:11; En 2:2; TestZeb 6:8; Philo; Jos., Ant. 14, 376; Ar. 4, 2) J 10:22 (oração breve como Polyaenus 7, 44, 2 <span class=\"greek\">πόλεμος</span> <span class=\"greek\">ἦν</span>, exc. 36, 8). <span class=\"greek\">χειμῶνος</span> no inverno (Pla., Rep. 3, 415e; X., Mem. 3, 8, 9; Appian, Illyr. 24 §70; SIG 495, 104f; cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">χειμῶνι</span> TestSol 10:7 C) Mt 24:20; Mk 13:18. <span class=\"greek\">πρὸ</span> <span class=\"greek\">χειμῶνος</span> antes do inverno (começar) 2 Ti 4:21.—Em linguagem figurada: <span class=\"greek\">χειμών</span> <span class=\"greek\">ἐστί</span> <span class=\"greek\">τινι</span> Hs 3, 2; 4, 2; <span class=\"greek\">τῷ</span> <span class=\"greek\">χειμῶνι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δένδρα</span> <span class=\"greek\">ἀποβάλλειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">φύλλα</span> as árvores perdem suas folhas no inverno 3:3.—B. 1013. DELG s.v. <span class=\"greek\">χεῖμα</span>. M-M.</p></section></article>"};
